export type GuideTaskId = keyof typeof guideTaskTexts;
export function guideTaskCopy(lang: string, id: GuideTaskId) {
    const index = ['it', 'en', 'es', 'fr', 'de', 'sv'].indexOf(lang);
    const [title, intro, first, second, third, note] = guideTaskTexts[id][index < 0 ? 1 : index].split('|');
    return { title, intro, steps: [first, second, third], note };
}
